1	/**
2	 * Public API endpoint for the storefront zip code widget.
3	 *
4	 * Called from the merchant's storefront (Theme App Extension or custom JS)
5	 * to check whether a zip code is serviceable.
6	 *
7	 * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
8	 *
9	 * Response:
10	 *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
11	 *   200 { allowed: false, message: "..." }
12	 *   400 { error: "Missing shop or zip parameter" }
13	 *   404 { allowed: false, message: "Zip code not found", notFound: true }
14	 */
15	import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
16	import db from "../db.server";
17	import { normalizeZipCode } from "../utils/zip";
18	import { rateLimit, getClientIp, rateLimitResponse } from "../utils/rate-limit.server";
19	import { getProductCollections } from "../utils/product-collections.server";
20	
21	function calculateDeliveryDate(
22	  estimatedDays: string,
23	  daysOfWeek: string | null,
24	): string | null {
25	  const match = estimatedDays.match(/^(\d+)/);
26	  if (!match) return null;
27	  const minDays = parseInt(match[1], 10);
28	  if (isNaN(minDays) || minDays < 0) return null;
29	
30	  const deliveryDayNames = daysOfWeek
31	    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
32	    : ["mon", "tue", "wed", "thu", "fri"];
33	
34	  const dayMap: Record<string, number> = {
35	    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
36	  };
37	  const deliveryDayNumbers = new Set(
38	    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
39	  );
40	
41	  if (deliveryDayNumbers.size === 0) {
42	    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
43	  }
44	
45	  const date = new Date();
46	  let businessDaysAdded = 0;
47	
48	  while (businessDaysAdded < minDays) {
49	    date.setDate(date.getDate() + 1);
50	    if (deliveryDayNumbers.has(date.getDay())) {
51	      businessDaysAdded++;
52	    }
53	  }
54	
55	  while (!deliveryDayNumbers.has(date.getDay())) {
56	    date.setDate(date.getDate() + 1);
57	  }
58	
59	  return date.toISOString().split("T")[0];
60	}
61	
62	const CORS_HEADERS = {
63	  "Access-Control-Allow-Origin": "*",
64	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
65	  "Access-Control-Allow-Headers": "Content-Type",
66	  "Content-Type": "application/json",
67	};
68	
69	// Applied only to successful (allowed) ZIP check responses to reduce DB load
70	// for repeated lookups of the same ZIP code from the same storefront visitor.
71	const SUCCESS_HEADERS = {
72	  ...CORS_HEADERS,
73	  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
74	};
75	
76	// Short cache for denied/not-found responses so merchants see changes quickly
77	// (e.g. when they add a new ZIP code it takes effect within 5 seconds).
78	const DENY_HEADERS = {
79	  ...CORS_HEADERS,
80	  "Cache-Control": "no-cache, max-age=5",
81	};
82	
83	const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
84	
85	/**
86	 * Returns true if a delivery rule's geographic constraints (zone or explicit
87	 * zip codes) match the given normalized zip and its zone.
88	 * Product/collection rules can optionally layer geographic constraints on top.
89	 * A rule with no zone and no zipCodes matches all geographies.
90	 */
91	function matchesZipOrZone(
92	  rule: { zipCodes: string | null; zone: string | null },
93	  normalizedZip: string,
94	  zipZone: string | null,
95	): boolean {
96	  if (rule.zipCodes?.trim()) {
97	    const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
98	    return zips.includes(normalizedZip);
99	  }
100	  if (rule.zone) {
101	    return rule.zone === zipZone;
102	  }
103	  // No geographic constraint — matches everywhere
104	  return true;
105	}
106	
107	async function handleZipCheck(
108	  shop: string | null,
109	  zip: string | null,
110	  productId?: string | null,
111	) {
112	  if (!shop || !zip) {
113	    return new Response(
114	      JSON.stringify({ error: "Missing shop or zip parameter" }),
115	      { status: 400, headers: CORS_HEADERS },
116	    );
117	  }
118	
119	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
120	  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
121	    return new Response(
122	      JSON.stringify({ error: "Invalid shop parameter" }),
123	      { status: 400, headers: CORS_HEADERS },
124	    );
125	  }
126	
127	  // Enforce input length limits to prevent abuse
128	  if (zip.length > 20) {
129	    return new Response(
130	      JSON.stringify({ error: "Invalid zip code" }),
131	      { status: 400, headers: CORS_HEADERS },
132	    );
133	  }
134	
135	  const normalizedZip = normalizeZipCode(zip);
136	
137	  try {
138	  const zipRecord = await db.zipCode.findUnique({
139	    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
140	  });
141	
142	  // Fetch widget config for custom messages (falls back to defaults)
143	  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
144	
145	  // Fetch shop settings to determine default behavior for unlisted zip codes
146	  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
147	  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
148	
149	  if (!zipRecord || !zipRecord.isActive) {
150	    const notFoundMsg =
151	      widgetConfig?.notFoundMessage ??
152	      "We currently do not ship to this ZIP code.";
153	
154	    // If the zip is simply not in the list (not inactive) and the merchant
155	    // has set defaultBehavior to "allow", treat it as an allowed zip
156	    if (!zipRecord && defaultBehavior === "allow") {
157	      const successMsg =
158	        widgetConfig?.successMessage ?? "We deliver to your area!";
159	      return new Response(
160	        JSON.stringify({
161	          allowed: true,
162	          message: successMsg,
163	          eta: null,
164	          zone: null,
165	          codAvailable: null,
166	          returnPolicy: null,
167	          showWaitlist: false,
168	          waitlistCount: 0,
169	          cutoffTime: null,
170	          daysOfWeek: null,
171	        }),
172	        { status: 200, headers: SUCCESS_HEADERS },
173	      );
174	    }
175	
176	    // Social proof: count how many customers are waiting for this ZIP
177	    let waitlistCount = 0;
178	    try {
179	      waitlistCount = await db.waitlistEntry.count({
180	        where: { shop, zipCode: normalizedZip, status: "waiting" },
181	      });
182	    } catch {
183	      waitlistCount = 0;
184	    }
185	
186	    if (!zipRecord) {
187	      return new Response(
188	        JSON.stringify({
189	          allowed: false,
190	          message: notFoundMsg,
191	          notFound: true,
192	          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
193	          waitlistCount,
194	        }),
195	        { status: 200, headers: DENY_HEADERS },
196	      );
197	    }
198	
199	    // Inactive zip — treat same as not found regardless of defaultBehavior
200	    return new Response(
201	      JSON.stringify({
202	        allowed: false,
203	        message: notFoundMsg,
204	        notFound: true,
205	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
206	        waitlistCount,
207	      }),
208	      { status: 200, headers: DENY_HEADERS },
209	    );
210	  }
211	
212	  if (zipRecord.type === "blocked") {
213	    const errorMsg =
214	      zipRecord.message ??
215	      widgetConfig?.errorMessage ??
216	      "Sorry, we don't deliver to this area yet.";
217	
218	    // Social proof: count how many customers are waiting for this ZIP
219	    let waitlistCount = 0;
220	    try {
221	      waitlistCount = await db.waitlistEntry.count({
222	        where: { shop, zipCode: normalizedZip, status: "waiting" },
223	      });
224	    } catch {
225	      waitlistCount = 0;
226	    }
227	
228	    return new Response(
229	      JSON.stringify({
230	        allowed: false,
231	        message: errorMsg,
232	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
233	        waitlistCount,
234	      }),
235	      { status: 200, headers: DENY_HEADERS },
236	    );
237	  }
238	
239	  // Fetch the most relevant active DeliveryRule for this zip.
240	  // Priority 1: rules that explicitly list this zip in their zipCodes field.
241	  // Priority 2: rules that match by zone (with no explicit zip list).
242	  // Within each priority tier, order by `priority ASC` (lower = higher priority).
243	  const zipCodeUpper = normalizedZip;
244	  const zipZone = zipRecord.zone ?? null;
245	
246	  // Fetch all active rules for the shop ordered by priority so we can apply
247	  // the matching logic in a single query result.
248	  const activeRules = await db.deliveryRule.findMany({
249	    where: { shop, isActive: true },
250	    orderBy: { priority: "asc" },
251	  });
252	
253	  let matchedRule: (typeof activeRules)[number] | null = null;
254	
255	  if (productId) {
256	    // Pass 1: product-specific rules — targetType "products", productIds contains this product
257	    for (const rule of activeRules) {
258	      if (rule.targetType === "products" && rule.productIds) {
259	        const ids = rule.productIds.split(",").map((id) => id.trim());
260	        if (ids.includes(productId)) {
261	          if (matchesZipOrZone(rule, zipCodeUpper, zipZone)) {
262	            matchedRule = rule;
263	            break;
264	          }
265	        }
266	      }
267	    }
268	
269	    // Pass 2: collection-specific rules — only run if collection-targeted rules exist
270	    if (!matchedRule) {
271	      const hasCollectionRules = activeRules.some(
272	        (r) => r.targetType === "collections",
273	      );
274	      if (hasCollectionRules) {
275	        const productCollections = await getProductCollections(shop, productId);
276	        for (const rule of activeRules) {
277	          if (rule.targetType === "collections" && rule.collectionIds) {
278	            const ruleCollectionIds = rule.collectionIds
279	              .split(",")
280	              .map((id) => id.trim());
281	            if (ruleCollectionIds.some((cid) => productCollections.includes(cid))) {
282	              if (matchesZipOrZone(rule, zipCodeUpper, zipZone)) {
283	                matchedRule = rule;
284	                break;
285	              }
286	            }
287	          }
288	        }
289	      }
290	    }
291	  }
292	
293	  // Pass 3: explicit zip match on general rules (targetType "all")
294	  if (!matchedRule) {
295	    for (const rule of activeRules) {
296	      if (rule.targetType === "all" && rule.zipCodes) {
297	        const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
298	        if (zips.includes(zipCodeUpper)) {
299	          matchedRule = rule;
300	          break;
301	        }
302	      }
303	    }
304	  }
305	
306	  // Pass 4: zone match on general rules — rule's zone matches and no explicit zip list
307	  if (!matchedRule && zipZone) {
308	    for (const rule of activeRules) {
309	      if (
310	        rule.targetType === "all" &&
311	        rule.zone === zipZone &&
312	        (!rule.zipCodes || rule.zipCodes.trim() === "")
313	      ) {
314	        matchedRule = rule;
315	        break;
316	      }
317	    }
318	  }
319	
320	  // Allowed
321	  const successMsg =
322	    zipRecord.message ??
323	    widgetConfig?.successMessage ??
324	    "Great news! We deliver to your area.";
325	
326	  // ETA: prefer the zip-level eta, then fall back to the matched delivery rule's
327	  // estimatedDays so merchants only need to populate one place.
328	  const etaValue = zipRecord.eta ?? matchedRule?.estimatedDays ?? null;
329	
330	  const estimatedDeliveryDate =
331	    widgetConfig?.showDeliveryDate !== false && etaValue
332	      ? calculateDeliveryDate(etaValue, matchedRule?.daysOfWeek ?? null)
333	      : null;
334	
335	  const rawDeliveryFee = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.deliveryFee ?? null) : null;
336	  const deliveryFeeValue = rawDeliveryFee != null && rawDeliveryFee >= 0 ? rawDeliveryFee : null;
337	  const rawFreeShippingAbove = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.freeShippingAbove ?? null) : null;
338	  const freeShippingAboveValue = rawFreeShippingAbove != null && rawFreeShippingAbove >= 0 ? rawFreeShippingAbove : null;
339	
340	  return new Response(
341	    JSON.stringify({
342	      allowed: true,
343	      message: successMsg,
344	      eta: widgetConfig?.showEta ? etaValue : null,
345	      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
346	      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
347	      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
348	      showWaitlist: false,
349	      waitlistCount: 0,
350	      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
351	      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
352	      estimatedDeliveryDate,
353	      deliveryFee: deliveryFeeValue,
354	      freeShippingAbove: freeShippingAboveValue,
355	    }),
356	    { status: 200, headers: SUCCESS_HEADERS },
357	  );
358	  } catch (err) {
359	    console.error("[api.zip-check] Unhandled error for shop=%s zip=%s:", shop, zip, err);
360	    return new Response(
361	      JSON.stringify({ error: "Internal server error" }),
362	      { status: 500, headers: CORS_HEADERS },
363	    );
364	  }
365	}
