367	// Rate limit: 60 requests per IP per minute (generous for storefront widget)
368	function checkRateLimit(request: Request): Response | null {
369	  const ip = getClientIp(request);
370	  const { limited, resetAt } = rateLimit(`zip-check:${ip}`, 60, 60_000);
371	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
372	  return null;
373	}
