375	// Handle GET requests: ?shop=...&zip=...
376	export const loader = async ({ request }: LoaderFunctionArgs) => {
377	  const url = new URL(request.url);
378	
379	  // Handle CORS preflight
380	  if (request.method === "OPTIONS") {
381	    return new Response(null, { status: 204, headers: CORS_HEADERS });
382	  }
383	
384	  const blocked = checkRateLimit(request);
385	  if (blocked) return blocked;
386	
387	  const shop = url.searchParams.get("shop");
388	  const zip = url.searchParams.get("zip");
389	  const product = url.searchParams.get("product");
390	  return handleZipCheck(shop, zip, product);
391	};
