393	// Handle POST requests with JSON body: { shop, zip }
394	export const action = async ({ request }: ActionFunctionArgs) => {
395	  const blocked = checkRateLimit(request);
396	  if (blocked) return blocked;
397	
398	  let shop: string | null = null;
399	  let zip: string | null = null;
400	
401	  let product: string | null = null;
402	
403	  try {
404	    const body = await request.json();
405	    shop = body?.shop ?? null;
406	    zip = body?.zip ?? null;
407	    product = body?.product ?? null;
408	  } catch {
409	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
410	      status: 400,
411	      headers: CORS_HEADERS,
412	    });
413	  }
414	
415	  return handleZipCheck(shop, zip, product);
416	};
