86	export const action = async ({ request }: ActionFunctionArgs) => {
87	  const { session } = await authenticate.admin(request);
88	  const shop = session.shop;
89	
90	  const formData = await request.formData();
91	  const intent = formData.get("intent") as string;
92	
93	  try {
94	    if (intent === "save-behavior") {
95	      const defaultBehavior = formData.get("defaultBehavior") as string;
96	      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
97	        return { error: "Invalid value for defaultBehavior" };
98	      }
99	      await db.shopSettings.upsert({
100	        where: { shop },
101	        create: { shop, defaultBehavior },
102	        update: { defaultBehavior },
103	      });
104	      return { success: true, intent };
105	    }
106	
107	    if (intent === "save-notification") {
108	      const notificationEmail =
109	        (formData.get("notificationEmail") as string | null) ?? "";
110	      await db.shopSettings.upsert({
111	        where: { shop },
112	        create: { shop, notificationEmail: notificationEmail || null },
113	        update: { notificationEmail: notificationEmail || null },
114	      });
115	      return { success: true, intent };
116	    }
117	
118	    if (intent === "save-email-settings") {
119	      const emailSenderName =
120	        (formData.get("emailSenderName") as string | null)?.trim() || null;
121	      const emailReplyTo =
122	        (formData.get("emailReplyTo") as string | null)?.trim() || null;
123	      await db.shopSettings.upsert({
124	        where: { shop },
125	        create: { shop, emailSenderName, emailReplyTo },
126	        update: { emailSenderName, emailReplyTo },
127	      });
128	      return { success: true, intent };
129	    }
130	
131	    if (intent === "send-test-email") {
132	      const testEmail = (formData.get("testEmail") as string | null) ?? "";
133	      if (!testEmail) return { error: "No email address provided." };
134	      if (!isEmailConfigured()) {
135	        return { error: "Email is not configured — RESEND_API_KEY environment variable is missing. Add it to your .env file and redeploy." };
136	      }
137	      const settings = await db.shopSettings.findUnique({ where: { shop } });
138	      const sent = await sendTestEmail(
139	        testEmail,
140	        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
141	        shop,
142	      );
143	      return sent
144	        ? { success: true, intent }
145	        : { error: "Failed to send test email via Resend. Verify your RESEND_API_KEY is valid and your sender domain is verified in the Resend dashboard." };
146	    }
147	
148	    return { error: "Unknown intent" };
149	  } catch {
150	    return { error: "Failed to save settings. Please try again." };
151	  }
152	};
