236	
237	export const action = async ({
238	  request,
239	}: ActionFunctionArgs): Promise<ActionResult> => {
240	  const { session } = await authenticate.admin(request);
241	  const shop = session.shop;
242	  const isAdmin = shop === ADMIN_SHOP;
243	  const formData = await request.formData();
244	  const intent = String(formData.get("intent") ?? "");
245	
246	  try {
247	    switch (intent) {
248	      case "submit": {
249	        const title = String(formData.get("title") ?? "").trim();
250	        const description = String(formData.get("description") ?? "").trim();
251	        const rawCategory = String(formData.get("category") ?? "General").trim();
252	        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
253	
254	        if (!title || !description) {
255	          return { error: "Title and description are required." };
256	        }
257	        if (title.length > 150) {
258	          return { error: "Title must be 150 characters or fewer." };
259	        }
260	        if (description.length > MAX_DESCRIPTION_LENGTH) {
261	          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
262	        }
263	
264	        // Per-shop submission limit
265	        const existingCount = await db.featureRequest.count({ where: { shop } });
266	        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
267	          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
268	        }
269	
270	        await db.featureRequest.create({
271	          data: { title, description, category, shop },
272	        });
273	
274	        return { success: true, intent: "submit" };
275	      }
276	
277	      case "vote": {
278	        const featureId = String(formData.get("featureId") ?? "").trim();
279	        if (!featureId) return { error: "Feature ID is required." };
280	
281	        const feature = await db.featureRequest.findUnique({
282	          where: { id: featureId },
283	        });
284	        if (!feature) return { error: "Feature request not found." };
285	
286	        const existing = await db.featureVote.findUnique({
287	          where: {
288	            featureRequestId_shop: { featureRequestId: featureId, shop },
289	          },
290	        });
291	
292	        let voted: boolean;
293	
294	        if (existing) {
295	          await db.featureVote.delete({ where: { id: existing.id } });
296	          // Atomic decrement
297	          const updated = await db.featureRequest.update({
298	            where: { id: featureId },
299	            data: { votesCount: { decrement: 1 } },
300	          });
301	          // Ensure count doesn't go below 0
302	          if (updated.votesCount < 0) {
303	            await db.featureRequest.update({
304	              where: { id: featureId },
305	              data: { votesCount: 0 },
306	            });
307	          }
308	          voted = false;
309	          const finalCount = Math.max(0, updated.votesCount);
310	          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
311	        } else {
312	          await db.featureVote.create({
313	            data: { featureRequestId: featureId, shop },
314	          });
315	          // Atomic increment
316	          const updated = await db.featureRequest.update({
317	            where: { id: featureId },
318	            data: { votesCount: { increment: 1 } },
319	          });
320	          voted = true;
321	          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
322	        }
323	      }
324	
325	      case "delete": {
326	        const deleteId = String(formData.get("id") ?? "").trim();
327	        if (!deleteId) return { error: "Feature ID is required." };
328	
329	        const toDelete = await db.featureRequest.findUnique({
330	          where: { id: deleteId },
331	        });
332	        if (!toDelete) return { error: "Feature request not found." };
333	
334	        // Admin can delete any, regular users only their own
335	        if (!isAdmin && toDelete.shop !== shop) {
336	          return { error: "You can only delete your own feature requests." };
337	        }
338	
339	        await db.featureRequest.delete({ where: { id: deleteId } });
340	        return { success: true, intent: "delete" };
341	      }
342	
343	      case "edit": {
344	        const editId = String(formData.get("id") ?? "").trim();
345	        const editTitle = String(formData.get("title") ?? "").trim();
346	        const editDescription = String(formData.get("description") ?? "").trim();
347	        const rawEditCategory = String(formData.get("category") ?? "General").trim();
348	        const editCategory = VALID_CATEGORIES.has(rawEditCategory) ? rawEditCategory : "General";
349	
350	        if (!editId) return { error: "Feature ID is required." };
351	        if (!editTitle || !editDescription) {
352	          return { error: "Title and description are required." };
353	        }
354	        if (editTitle.length > 150) {
355	          return { error: "Title must be 150 characters or fewer." };
356	        }
357	        if (editDescription.length > MAX_DESCRIPTION_LENGTH) {
358	          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
359	        }
360	
361	        const toEdit = await db.featureRequest.findUnique({ where: { id: editId } });
362	        if (!toEdit) return { error: "Feature request not found." };
363	
364	        if (!isAdmin && toEdit.shop !== shop) {
365	          return { error: "You can only edit your own feature requests." };
366	        }
367	
368	        const editData: { title: string; description: string; category: string; status?: string } = {
369	          title: editTitle,
370	          description: editDescription,
371	          category: editCategory,
372	        };
373	
374	        // Admin can also change status via the edit form
375	        const editStatus = String(formData.get("status") ?? "").trim();
376	        if (isAdmin && editStatus && VALID_STATUSES.has(editStatus)) {
377	          editData.status = editStatus;
378	        }
379	
380	        await db.featureRequest.update({
381	          where: { id: editId },
382	          data: editData,
383	        });
384	
385	        return { success: true, intent: "edit" };
386	      }
387	
388	      case "update-status": {
389	        if (!isAdmin) {
390	          return { error: "Only the app admin can change request statuses." };
391	        }
392	
393	        const statusId = String(formData.get("id") ?? "").trim();
394	        const newStatus = String(formData.get("status") ?? "").trim();
395	
396	        if (!statusId) return { error: "Feature ID is required." };
397	        if (!VALID_STATUSES.has(newStatus)) {
398	          return { error: "Invalid status value." };
399	        }
400	
401	        const toUpdate = await db.featureRequest.findUnique({
402	          where: { id: statusId },
403	        });
404	        if (!toUpdate) return { error: "Feature request not found." };
405	
406	        await db.featureRequest.update({
407	          where: { id: statusId },
408	          data: { status: newStatus },
409	        });
410	
411	        return { success: true, intent: "update-status" };
412	      }
413	
414	      default:
415	        return { error: "Unknown action." };
416	    }
417	  } catch (err) {
418	    const message =
419	      err instanceof Error ? err.message : "An unexpected error occurred.";
420	    return { error: message };
421	  }
422	};
